package com.wackysire;

import net.runelite.api.gameval.NpcID;

final class TentacleIds
{
	private TentacleIds()
	{
	}

	static boolean matches(int id)
	{
		switch (id)
		{
			case NpcID.ABYSSALSIRE_TENTACLE_SLEEPING_NORTH:
			case NpcID.ABYSSALSIRE_TENTACLE_SLEEPING_SOUTH:
			case NpcID.ABYSSALSIRE_TENTACLE_SLEEPING_UPRIGHT:
			case NpcID.ABYSSALSIRE_TENTACLE_ACTIVE:
			case NpcID.ABYSSALSIRE_TENTACLE_STUNNED:
				return true;
			default:
				return false;
		}
	}
}

package com.wackysire;

import java.util.ArrayList;
import java.util.List;

/** Original procedural geometry. Negative Y points up in the game coordinate system. */
final class TubeMesh
{
	static final int BODY = 0;
	static final int WHITE = 1;
	static final int BLACK = 2;
	static final int BASE = 3;
	private static final int SIDES = 8;
	private final List<Triangle> faces = new ArrayList<>();

	List<Triangle> getFaces()
	{
		return faces;
	}

	static TubeMesh pose(double seconds, double phase)
	{
		TubeMesh mesh = new TubeMesh();
		double t = seconds * 2.6 + phase;
		Vec[] body = new Vec[11];
		for (int i = 0; i < body.length; i++)
		{
			double h = i / 10.0;
			body[i] = new Vec(Math.sin(t + h * 2.1) * 68 * h * h, -h * 340,
				Math.cos(t + h * 1.7) * 35 * h * h);
		}
		mesh.tube(body, 28, BODY);
		mesh.tube(new Vec[]{new Vec(0, 0, 0), new Vec(0, -22, 0)}, 40, BASE);
		Vec shoulder = body[7];
		for (int side : new int[]{-1, 1})
		{
			Vec[] arm = new Vec[6];
			for (int i = 0; i < arm.length; i++)
			{
				double u = i / 5.0;
				arm[i] = shoulder.add(new Vec(side * (20 + u * 105),
					-u * 25 - Math.sin(t * 2 + side + u * 3) * 56 * u,
					Math.cos(t + side + u * 2) * 24 * u));
			}
			mesh.tube(arm, 11, BODY);
		}
		// Face panels on the front of the top section, following the head's lean.
		Vec head = body[9];
		Vec right = new Vec(1, 0, 0);
		Vec up = body[10].subtract(body[8]).unit();
		Vec front = right.cross(up).unit();
		for (int side : new int[]{-1, 1})
		{
			Vec eye = head.add(right.times(side * 11)).add(front.times(29));
			mesh.panel(eye, right, up, 8, 10, WHITE);
			mesh.panel(eye.add(front.times(1)), right, up, 3, 5, BLACK);
		}
		mesh.panel(head.add(up.times(-22)).add(front.times(29)), right, up, 13, 5, BLACK);
		// Five little fabric streamers above the open head.
		for (int i = -2; i <= 2; i++)
		{
			Vec root = body[10].add(new Vec(i * 10, 0, 0));
			Vec tip = root.add(new Vec(Math.sin(t * 2 + i) * 18, -30,
				Math.cos(t * 2 + i) * 16));
			mesh.tube(new Vec[]{root, tip}, 3, BODY);
		}
		return mesh;
	}

	private void panel(Vec center, Vec right, Vec up, double width, double height, int color)
	{
		Vec a = center.add(right.times(-width)).add(up.times(-height));
		Vec b = center.add(right.times(width)).add(up.times(-height));
		Vec c = center.add(right.times(width)).add(up.times(height));
		Vec d = center.add(right.times(-width)).add(up.times(height));
		triangle(a, b, c, color);
		triangle(a, c, d, color);
	}

	private void tube(Vec[] centers, double radius, int color)
	{
		Vec[][] rings = new Vec[centers.length][SIDES];
		// Use one reference axis for the whole tube: switching it between rings
		// twists the surface abruptly where a bent segment crosses a threshold.
		Vec main = centers[centers.length - 1].subtract(centers[0]).unit();
		Vec axis = Math.abs(main.y) > 0.9 ? new Vec(1, 0, 0) : new Vec(0, 1, 0);
		for (int r = 0; r < centers.length; r++)
		{
			Vec tangent = centers[Math.min(r + 1, centers.length - 1)]
				.subtract(centers[Math.max(0, r - 1)]).unit();
			Vec a = tangent.cross(axis).unit();
			Vec b = tangent.cross(a).unit();
			for (int s = 0; s < SIDES; s++)
			{
				double angle = s * Math.PI * 2 / SIDES;
				rings[r][s] = centers[r].add(a.times(Math.cos(angle) * radius))
					.add(b.times(Math.sin(angle) * radius));
			}
		}
		for (int r = 0; r < rings.length - 1; r++)
		{
			for (int s = 0; s < SIDES; s++)
			{
				int n = (s + 1) % SIDES;
				triangle(rings[r][s], rings[r][n], rings[r + 1][n], color);
				triangle(rings[r][s], rings[r + 1][n], rings[r + 1][s], color);
			}
		}
	}

	private void triangle(Vec a, Vec b, Vec c, int color)
	{
		// Both windings keep open fabric tubes visible from inside and outside.
		faces.add(new Triangle(a, b, c, color));
		faces.add(new Triangle(c, b, a, color));
	}

	static final class Triangle
	{
		final Vec a;
		final Vec b;
		final Vec c;
		final int color;

		Triangle(Vec a, Vec b, Vec c, int color)
		{
			this.a = a;
			this.b = b;
			this.c = c;
			this.color = color;
		}
	}

	static final class Vec
	{
		final double x;
		final double y;
		final double z;

		Vec(double x, double y, double z)
		{
			this.x = x;
			this.y = y;
			this.z = z;
		}

		Vec add(Vec v) { return new Vec(x + v.x, y + v.y, z + v.z); }
		Vec subtract(Vec v) { return new Vec(x - v.x, y - v.y, z - v.z); }
		Vec times(double n) { return new Vec(x * n, y * n, z * n); }
		Vec cross(Vec v) { return new Vec(y * v.z - z * v.y, z * v.x - x * v.z, x * v.y - y * v.x); }
		Vec unit()
		{
			double length = Math.sqrt(x * x + y * y + z * z);
			if (length < 0.000001)
			{
				throw new IllegalArgumentException("Zero-length mesh direction");
			}
			return times(1 / length);
		}
	}
}

package com.wackysire;

import java.util.Arrays;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;

/** Uses a cache triangle only as an allocation primitive; no cache arrays are modified. */
final class TubeModelFactory
{
	// Cache model 823 is a single untextured triangle (3 vertices, 1 face).
	private static final int TRIANGLE_MODEL = 823;
	private static final int[] HUES = {0, 10, 22, 33, 43, 53};
	static final int FRAME_COUNT = 64;
	// Share immutable poses across every tentacle. No per-tick mesh allocation.
	private static final TubeMesh[] POSES = makePoses();
	private final Client client;
	private ModelData template;

	@Inject
	TubeModelFactory(Client client)
	{
		this.client = client;
	}

	Model create(int palette, int phase)
	{
		TubeMesh pose = POSES[Math.floorMod(phase, FRAME_COUNT)];
		if (template == null)
		{
			ModelData seed = client.loadModelData(TRIANGLE_MODEL);
			if (seed == null)
			{
				return null; // Asset download may still be in progress; the plugin retries.
			}
			if (seed.getVerticesCount() != 3 || seed.getFaceCount() != 1)
			{
				throw new IllegalStateException("Cache triangle 823 changed; originals will stay visible");
			}
			ModelData[] parts = new ModelData[pose.getFaces().size()];
			for (int i = 0; i < parts.length; i++)
			{
				// mergeModels deduplicates matching coordinates. Separate each seed by
				// a large translation so each output triangle owns three vertices.
				parts[i] = seed.shallowCopy().cloneVertices().translate(i * 1024, 0, 0);
			}
			template = client.mergeModels(parts);
			if (template.getFaceCount() != parts.length || template.getVerticesCount() != parts.length * 3)
			{
				template = null;
				throw new IllegalStateException("Unexpected triangle merge shape; originals will stay visible");
			}
		}
		ModelData data = template.shallowCopy().cloneVertices().cloneColors()
			.cloneTransparencies(true);
		// Untextured cache models have no texture array; cloneTextures requires one.
		if (data.getFaceTextures() != null)
		{
			data.cloneTextures();
		}
		writeVertices(data.getVerticesX(), data.getVerticesY(), data.getVerticesZ(),
			data.getFaceIndices1(), data.getFaceIndices2(), data.getFaceIndices3(), pose);
		short[] colors = {
			JagexColor.packHSL(HUES[Math.floorMod(palette, HUES.length)], 7, 64),
			JagexColor.packHSL(0, 0, 120),
			JagexColor.packHSL(0, 0, 8),
			JagexColor.packHSL(0, 0, 28)
		};
		for (int i = 0; i < data.getFaceCount(); i++)
		{
			data.getFaceColors()[i] = colors[pose.getFaces().get(i).color];
		}
		Arrays.fill(data.getFaceTransparencies(), (byte) 0);
		if (data.getFaceTextures() != null)
		{
			Arrays.fill(data.getFaceTextures(), (short) -1);
		}
		return data.light();
	}

	static int frame(double seconds, int phase)
	{
		return Math.floorMod((int) (seconds * 2.6 * FRAME_COUNT / (Math.PI * 2)) + phase, FRAME_COUNT);
	}

	static void animate(Model model, int frame)
	{
		writeVertices(model.getVerticesX(), model.getVerticesY(), model.getVerticesZ(),
			model.getFaceIndices1(), model.getFaceIndices2(), model.getFaceIndices3(),
			POSES[Math.floorMod(frame, FRAME_COUNT)]);
		// A no-op scale invalidates native model bounds after direct vertex writes.
		model.scale(128, 128, 128);
		model.calculateBoundsCylinder();
	}

	private static TubeMesh[] makePoses()
	{
		TubeMesh[] poses = new TubeMesh[FRAME_COUNT];
		for (int i = 0; i < poses.length; i++)
		{
			poses[i] = TubeMesh.pose(0, i * Math.PI * 2 / FRAME_COUNT);
		}
		return poses;
	}

	private static void writeVertices(float[] x, float[] y, float[] z,
		int[] a, int[] b, int[] c, TubeMesh pose)
	{
		List<TubeMesh.Triangle> faces = pose.getFaces();
		for (int i = 0; i < faces.size(); i++)
		{
			TubeMesh.Triangle face = faces.get(i);
			put(x, y, z, a[i], face.a);
			put(x, y, z, b[i], face.b);
			put(x, y, z, c[i], face.c);
		}
	}

	private static void put(float[] x, float[] y, float[] z, int i, TubeMesh.Vec v)
	{
		x[i] = (float) v.x;
		y[i] = (float) v.y;
		z[i] = (float) v.z;
	}

	void clear()
	{
		template = null;
	}
}

package com.wackysire;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(WackySireConfig.GROUP)
public interface WackySireConfig extends Config
{
	String GROUP = "wackysire";

	@ConfigItem(keyName = "keepOriginals", name = "Keep original tentacles visible",
		description = "Draw both models. Replacement mode hides the original client clickboxes.", position = 0)
	default boolean keepOriginals()
	{
		return false;
	}
}

package com.wackysire;

import com.google.inject.Provides;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.Renderable;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.PostClientTick;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(name = "Wacky Sire",
	description = "Cosmetic flailing inflatable tube men in place of Abyssal Sire tentacles",
	tags = {"sire", "abyssal", "tentacle", "cosmetic", "inflatable"})
public class WackySirePlugin extends Plugin implements RenderCallback
{
	private static final Logger log = LoggerFactory.getLogger(WackySirePlugin.class);
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private WackySireConfig config;
	@Inject private RenderCallbackManager renderCallbacks;
	@Inject private TubeModelFactory modelFactory;
	private final Map<NPC, TubeMan> tubes = new IdentityHashMap<>();
	private volatile boolean running;
	private boolean modelFailure;
	private int ticks;

	@Provides
	WackySireConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(WackySireConfig.class);
	}

	@Override
	protected void startUp()
	{
		running = true;
		clientThread.invoke(() ->
		{
			if (running)
			{
				modelFailure = false;
				ticks = 0;
			}
		});
		renderCallbacks.register(this);
		// PostClientTick seeds NPCs already loaded when enabled and retries pending assets.
	}

	@Override
	protected void shutDown()
	{
		running = false;
		renderCallbacks.unregister(this);
		clientThread.invoke(() ->
		{
			clear();
			modelFactory.clear();
		});
	}

	@Override
	public boolean addEntity(Renderable renderable, boolean ui)
	{
		// Keep original UI and fail open if a replacement is not active.
		if (!running || ui || config.keepOriginals() || !(renderable instanceof NPC))
		{
			return true;
		}
		NPC npc = (NPC) renderable;
		TubeMan tube = tubes.get(npc);
		return !TentacleIds.matches(npc.getId()) || tube == null || !tube.object.isActive();
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		track(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		NPC npc = event.getNpc();
		if (TentacleIds.matches(npc.getId()))
		{
			track(npc);
		}
		else
		{
			remove(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		remove(event.getNpc());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			clear(); // Loading, hopping and logout cannot leave old scene objects behind.
		}
	}

	@Subscribe
	public void onPostClientTick(PostClientTick event)
	{
		if (!running || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		ticks++;
		// Scan twice a second for enable-mid-fight and cache download retries.
		if (ticks == 1 || ticks % 25 == 0)
		{
			for (NPC npc : client.getTopLevelWorldView().npcs())
			{
				track(npc);
			}
		}
		Iterator<Map.Entry<NPC, TubeMan>> iterator = tubes.entrySet().iterator();
		while (iterator.hasNext())
		{
			Map.Entry<NPC, TubeMan> entry = iterator.next();
			NPC npc = entry.getKey();
			TubeMan tube = entry.getValue();
			LocalPoint point = npc.getLocalLocation();
			if (!TentacleIds.matches(npc.getId()) || point == null ||
				point.getWorldView() != client.getTopLevelWorldView().getId())
			{
				tube.object.setActive(false);
				iterator.remove();
				continue;
			}
			tube.object.setLocation(point, client.getTopLevelWorldView().getPlane());
			tube.object.setOrientation(npc.getCurrentOrientation());
			int frame = TubeModelFactory.frame(ticks * 0.02, tube.phase);
			if (frame != tube.lastFrame)
			{
				TubeModelFactory.animate(tube.model, frame);
				tube.lastFrame = frame;
			}
			if (!tube.object.isActive())
			{
				tube.object.setActive(true);
			}
		}
	}

	private void track(NPC npc)
	{
		if (!running || modelFailure || client.getGameState() != GameState.LOGGED_IN ||
			!TentacleIds.matches(npc.getId()) || tubes.containsKey(npc))
		{
			return;
		}
		LocalPoint point = npc.getLocalLocation();
		if (point == null || point.getWorldView() != client.getTopLevelWorldView().getId())
		{
			return;
		}
		try
		{
			// Stable colors and phases from the location, independent of combat state.
			int seed = point.getSceneX() * 31 + point.getSceneY();
			int phase = Math.floorMod(seed, TubeModelFactory.FRAME_COUNT);
			Model model = modelFactory.create(seed, phase);
			if (model == null)
			{
				return;
			}
			RuneLiteObject object = new RuneLiteObject(client);
			object.setModel(model);
			object.setLocation(point, client.getTopLevelWorldView().getPlane());
			object.setOrientation(npc.getCurrentOrientation());
			object.setRenderMode(Renderable.RENDERMODE_SORTED);
			object.setActive(true);
			tubes.put(npc, new TubeMan(object, model, phase));
		}
		catch (RuntimeException ex)
		{
			modelFailure = true;
			clear();
			log.warn("Wacky Sire model creation failed; keeping original tentacles visible. Re-enable to retry.", ex);
		}
	}

	private void remove(NPC npc)
	{
		TubeMan tube = tubes.remove(npc);
		if (tube != null)
		{
			tube.object.setActive(false);
		}
	}

	private void clear()
	{
		for (TubeMan tube : tubes.values())
		{
			tube.object.setActive(false);
		}
		tubes.clear();
	}

	private static final class TubeMan
	{
		private final RuneLiteObject object;
		private final Model model;
		private final int phase;
		private int lastFrame;

		private TubeMan(RuneLiteObject object, Model model, int phase)
		{
			this.object = object;
			this.model = model;
			this.phase = phase;
			this.lastFrame = phase;
		}
	}
}

package com.wackysire;

import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;

/** Exports the actual procedural animation for an offline artwork preview. Not a game screenshot. */
public class MeshPreview
{
	public static void main(String[] args) throws Exception
	{
		try (PrintWriter writer = new PrintWriter(Files.newBufferedWriter(Paths.get(args[0]), StandardCharsets.UTF_8)))
		{
			writer.print('[');
			for (int frame = 0; frame < 48; frame++)
			{
				if (frame != 0) { writer.print(','); }
				writer.print('[');
				boolean first = true;
				for (TubeMesh.Triangle triangle : TubeMesh.pose(0, frame * Math.PI * 2 / 48).getFaces())
				{
					if (!first) { writer.print(','); }
					first = false;
					writer.print("[" + triangle.color);
					for (TubeMesh.Vec vertex : new TubeMesh.Vec[]{triangle.a, triangle.b, triangle.c})
					{
						writer.print("," + vertex.x + "," + vertex.y + "," + vertex.z);
					}
					writer.print(']');
				}
				writer.print(']');
			}
			writer.print(']');
		}
	}
}

package com.wackysire;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class TubeMeshTest
{
	@Test
	public void posesStayFiniteAndKeepTheirTopology()
	{
		int count = TubeMesh.pose(0, 0).getFaces().size();
		for (int step = 0; step < 400; step++)
		{
			List<TubeMesh.Triangle> faces = TubeMesh.pose(step * 0.037, step * 0.13).getFaces();
			assertEquals(count, faces.size());
			for (TubeMesh.Triangle face : faces)
			{
				assertVertex(face.a);
				assertVertex(face.b);
				assertVertex(face.c);
				TubeMesh.Vec normal = face.b.subtract(face.a).cross(face.c.subtract(face.a));
				assertTrue(normal.x * normal.x + normal.y * normal.y + normal.z * normal.z > 0.001);
			}
		}
		assertTrue(count * 3 < 4096);
	}

	@Test
	public void theAnimationLoopsWithoutAGeometryJump()
	{
		List<TubeMesh.Triangle> a = TubeMesh.pose(0, 0).getFaces();
		List<TubeMesh.Triangle> b = TubeMesh.pose(0, Math.PI * 2).getFaces();
		for (int i = 0; i < a.size(); i++)
		{
			assertEquals(a.get(i).a.x, b.get(i).a.x, 0.000001);
			assertEquals(a.get(i).a.y, b.get(i).a.y, 0.000001);
			assertEquals(a.get(i).a.z, b.get(i).a.z, 0.000001);
		}
	}

	@Test
	public void eachFabricFaceHasItsReverseWinding()
	{
		List<TubeMesh.Triangle> faces = TubeMesh.pose(0, 0).getFaces();
		for (int i = 0; i < faces.size(); i += 2)
		{
			assertSame(faces.get(i).a, faces.get(i + 1).c);
			assertSame(faces.get(i).b, faces.get(i + 1).b);
			assertSame(faces.get(i).c, faces.get(i + 1).a);
		}
	}

	@Test
	public void animationMovesTheFabricAndLeavesTheBlowerAnchored()
	{
		List<TubeMesh.Triangle> a = TubeMesh.pose(0, 0).getFaces();
		List<TubeMesh.Triangle> b = TubeMesh.pose(0.5, 0).getFaces();
		boolean moved = false;
		for (int i = 0; i < a.size(); i++)
		{
			TubeMesh.Vec va = a.get(i).a;
			TubeMesh.Vec vb = b.get(i).a;
			if (a.get(i).color == TubeMesh.BASE)
			{
				assertEquals(va.x, vb.x, 0);
				assertEquals(va.y, vb.y, 0);
				assertEquals(va.z, vb.z, 0);
			}
			moved |= Math.abs(va.x - vb.x) > 1;
		}
		assertTrue(moved);
	}

	@Test
	public void onlySireTentaclesAreMatched()
	{
		for (int id = 5800; id < 6000; id++)
		{
			assertEquals(id >= 5909 && id <= 5913, TentacleIds.matches(id));
		}
		assertFalse(TentacleIds.matches(5535)); // Kraken
		assertFalse(TentacleIds.matches(12208)); // Whisperer
	}

	private static void assertVertex(TubeMesh.Vec vertex)
	{
		assertTrue(Double.isFinite(vertex.x));
		assertTrue(Double.isFinite(vertex.y));
		assertTrue(Double.isFinite(vertex.z));
		assertTrue(Math.abs(vertex.x) < 240);
		assertTrue(vertex.y <= 15 && vertex.y >= -400);
		assertTrue(Math.abs(vertex.z) < 100);
	}
}

